        GetStarterInventoryItems(uint accountUid) =>
        AccountUidRules.IsTest(accountUid)
            ? TestStarterInventoryItems
            : AccountUidRules.IsNormal(accountUid)
                ? NormalStarterInventoryItems
                : [];

